// ─── Hooks ───────────────────────────────────────────────────────────────────
function useInView(threshold = 0.1) {
  const ref = useRef(null);
  const [v, setV] = useState(false);
  useEffect(() => {
    if (!ref.current) return;
    const o = new IntersectionObserver(([e]) => { if (e.isIntersecting) { setV(true); o.disconnect(); } }, { threshold });
    o.observe(ref.current);
    return () => o.disconnect();
  }, []);
  return [ref, v];
}

function Reveal({ children, delay = 0, y = 24 }) {
  const [ref, v] = useInView();
  return (
    <div ref={ref} style={{ opacity: v ? 1 : 0, transform: v ? "none" : `translateY(${y}px)`, transition: `opacity .55s ease ${delay}s, transform .55s ease ${delay}s` }}>
      {children}
    </div>
  );
}

function Counter({ to, suffix = "" }) {
  const [n, setN] = useState(0);
  const [ref, v] = useInView();
  useEffect(() => {
    if (!v) return;
    let s = 0;
    const id = setInterval(() => { s = Math.min(s + to / 70, to); setN(Math.floor(s)); if (s >= to) clearInterval(id); }, 18);
    return () => clearInterval(id);
  }, [v, to]);
  return <span ref={ref}>{n}{suffix}</span>;
}

// ─── CV download ─────────────────────────────────────────────────────────────
function downloadCV() {
  const b = atob(CV_B64), arr = new Uint8Array(b.length);
  for (let i = 0; i < b.length; i++) arr[i] = b.charCodeAt(i);
  const url = URL.createObjectURL(new Blob([arr], { type: "application/pdf" }));
  Object.assign(document.createElement("a"), { href: url, download: "Romel_Musico_CV.pdf" }).click();
  URL.revokeObjectURL(url);
}

