function getReply(msg) {
  const l = msg.toLowerCase();
  for (const [k, v] of Object.entries(REPLIES)) if (l.includes(k)) return v;
  return { t: "Thanks for your interest! I can help with customer support, IT support, AI automation, virtual assistance, pricing, or availability. Tell me what you need and I’ll guide you. ✨", c: "General" };
}

