// ─── Shared primitives ────────────────────────────────────────────────────────
function Tag({ label, color, bg }) {
  return <span style={{ fontSize: 11, fontWeight: 600, padding: "2px 9px", borderRadius: 20, background: bg, color, letterSpacing: 0.3 }}>{label}</span>;
}

function SectionEyebrow({ t, sup, title }) {
  return (
    <div style={{ marginBottom: 44 }}>
      <div style={{ fontSize: 11, fontWeight: 700, letterSpacing: 4, color: t.accent, textTransform: "uppercase", marginBottom: 8 }}>{sup}</div>
      <h2 style={{ fontSize: "clamp(24px,3.5vw,36px)", fontWeight: 800, color: t.text, lineHeight: 1.15 }}>
        {title}
        <span style={{ display: "block", width: 40, height: 3, marginTop: 12, borderRadius: 2, background: `linear-gradient(90deg,${t.accent},${t.cyan})` }} />
      </h2>
    </div>
  );
}

